505	// This function is passed to string.replace(re[t.HYPHENRANGE])
506	// M, m, patch, prerelease, build
507	// 1.2 - 3.4.5 => >=1.2.0 <=3.4.5
508	// 1.2.3 - 3.4 => >=1.2.0 <3.5.0-0 Any 3.4.x will do
509	// 1.2 - 3.4 => >=1.2.0 <3.5.0-0
510	// TODO build?
511	const hyphenReplace = incPr => ($0,
512	  from, fM, fm, fp, fpr, fb,
513	  to, tM, tm, tp, tpr) => {
514	  if (isX(fM)) {
515	    from = ''
516	  } else if (isX(fm)) {
517	    from = `>=${fM}.0.0${incPr ? '-0' : ''}`
518	  } else if (isX(fp)) {
519	    from = `>=${fM}.${fm}.0${incPr ? '-0' : ''}`
520	  } else if (fpr) {
521	    from = `>=${from}`
522	  } else {
523	    from = `>=${from}${incPr ? '-0' : ''}`
524	  }
525	
526	  if (isX(tM)) {
527	    to = ''
528	  } else if (isX(tm)) {
529	    to = `<${+tM + 1}.0.0-0`
530	  } else if (isX(tp)) {
531	    to = `<${tM}.${+tm + 1}.0-0`
532	  } else if (tpr) {
533	    to = `<=${tM}.${tm}.${tp}-${tpr}`
534	  } else if (incPr) {
535	    to = `<${tM}.${tm}.${+tp + 1}-0`
536	  } else {
537	    to = `<=${to}`
538	  }
539	
540	  return `${from} ${to}`.trim()
541	}
542	
543	const testSet = (set, version, options) => {
544	  for (let i = 0; i < set.length; i++) {
545	    if (!set[i].test(version)) {
546	      return false
547	    }
548	  }
549	
550	  if (version.prerelease.length && !options.includePrerelease) {
551	    // Find the set of versions that are allowed to have prereleases
552	    // For example, ^1.2.3-pr.1 desugars to >=1.2.3-pr.1 <2.0.0
553	    // That should allow `1.2.3-pr.2` to pass.
554	    // However, `1.2.4-alpha.notready` should NOT be allowed,
555	    // even though it's within the range set by the comparators.
556	    for (let i = 0; i < set.length; i++) {
557	      debug(set[i].semver)
558	      if (set[i].semver === Comparator.ANY) {
559	        continue
560	      }
561	
562	      if (set[i].semver.prerelease.length > 0) {
563	        const allowed = set[i].semver
564	        if (allowed.major === version.major &&
565	            allowed.minor === version.minor &&
566	            allowed.patch === version.patch) {
567	          return true
568	        }
569	      }
570	    }
571	
572	    // Version has a -pre, but it's not one of the ones we like.
573	    return false
574	  }
575	
576	  return true
577	}
